console.log('step lvl1 dt.05 =', 260*0.05, '| lvl5 =', 620*0.05, '| lvl6 =', 710*0.05, '| lvl10 =', 1070*0.05);
console.log('brick skip distance =', BRICK_H + 2*BALL_R);
