  let flippedX = false;
  let flippedY = false;
  const EPS = 0.01;
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    const fromRight = brick.x + brick.w - (ball.x - ball.r);   // ball must move right
    const fromLeft = ball.x + ball.r - brick.x;                 // ball must move left
    const fromBottom = brick.y + brick.h - (ball.y - ball.r);   // ball must move down
    const fromTop = ball.y + ball.r - brick.y;                  // ball must move up
