// --- Physics (movement + wall/paddle/brick bounces) -----------------------

// The ball is moved in sub-steps of at most one ball radius. A single discrete
// step longer than the obstacle it crosses would skip it entirely (tunneling):
// with `ballSpeed(6) * 0.05 = 35.5px > BRICK_H + 2*BALL_R = 34px` the ball can
// jump over a whole brick in one frame. Sub-steps keep every sample within
// `BALL_R` px of the previous one, so no 34px obstacle can hide between two
// samples.
const PHYSICS_SUB_STEP = BALL_R;

// True if the ball (circle) overlaps the paddle AABB — closest-point test.
// The old center-in-rectangle test missed corner grazes: a ball whose center
// is just outside the paddle still visually touches it and must bounce.
function paddleOverlap(ball, paddle) {
  const cx = Math.max(paddle.x, Math.min(ball.x, paddle.x + paddle.w));
  const cy = Math.max(paddle.y, Math.min(ball.y, paddle.y + paddle.h));
  const dx = ball.x - cx;
  const dy = ball.y - cy;
  return dx * dx + dy * dy <= ball.r * ball.r;
}

// Bounces the ball off every live brick it overlaps and breaks that brick.
// The bounce axis is the axis of smallest penetration; the ball is pushed out
// of the brick along that axis so it never re-collides with the same face.
function bounceBricks(state) {
  const { ball, bricks } = state;
  const EPS = 0.01;
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    const fromRight = brick.x + brick.w - (ball.x - ball.r); // push right
    const fromLeft = ball.x + ball.r - brick.x; // push left
    const fromBottom = brick.y + brick.h - (ball.y - ball.r); // push down
    const fromTop = ball.y + ball.r - brick.y; // push up
    const penX = Math.min(fromRight, fromLeft);
    const penY = Math.min(fromBottom, fromTop);

    if (penX < penY) {
      ball.vx = -ball.vx;
      ball.x += (fromRight < fromLeft ? 1 : -1) * (penX + EPS);
    } else {
      ball.vy = -ball.vy;
      ball.y += (fromBottom < fromTop ? 1 : -1) * (penY + EPS);
    }
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const travel = Math.hypot(ball.vx, ball.vy) * dt;
  const subSteps = Math.max(1, Math.ceil(travel / PHYSICS_SUB_STEP));
  const h = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (ball.vy > 0 && paddleOverlap(ball, paddle)) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks
    bounceBricks(state);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

