// Paddle
if (ball.vy > 0 && paddleOverlap(ball, paddle)) {
  ball.y = paddle.y - ball.r;
  ball.vy = -Math.abs(ball.vy);
  // The rebound angle depends on where the paddle was hit.
  const hit = Math.max(-1, Math.min(1, (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2)));
  let vx = ballSpeed(state.level) * 0.6 * hit;
  // Angle-mort guard: a dead-center hit gives vx = 0 and locks the ball in
  // a vertical loop it can never leave — enforce a minimum horizontal
  // speed so every trajectory stays playable.
  const minVx = ballSpeed(state.level) * 0.1;
  if (Math.abs(vx) < minVx) vx = (vx < 0 ? -1 : 1) * minVx;
  ball.vx = vx;
  state.combo = 0; // touching the paddle resets the combo
}

